<?php declare(strict_types=1); require_once __DIR__.'/../includes/auth.php'; require_admin(); require_once __DIR__.'/../includes/csrf.php'; require_once __DIR__.'/../config/database.php';$users=$conn->query('SELECT id,fname,mname,lname,designation,department,username,status,datecreated,type FROM dr_users ORDER BY lname,fname')->fetch_all(MYSQLI_ASSOC);$page_title='User accounts';$page_heading='User accounts';$active_page='users';require __DIR__.'/../includes/app-shell.php'; ?>
<section class="panel data-wrap"><table class="data-table"><thead><tr><th>Created</th><th>Name</th><th>Designation</th><th>Department</th><th>Username</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($users as $account): ?><tr><td><?= e($account['datecreated']) ?></td><td><?= e(user_name($account)) ?></td><td><?= e($account['designation']) ?></td><td><?= e($account['department']) ?></td><td><?= e($account['username']) ?></td><td><span class="badge <?= $account['status']==='Inactive'?'badge-danger':'badge-success' ?>"><?= e($account['status']?:'Unspecified') ?></span></td><td><?php if((int)$account['id']!==(int)$_SESSION['user_id']): ?><form method="post" action="<?= url('actions/toggle-user-status.php') ?>"><?= csrf_input() ?><input type="hidden" name="user_id" value="<?= $account['id'] ?>"><button class="btn btn-secondary" type="submit" data-confirm="Change this account's status?"><?= $account['status']==='Inactive'?'Activate':'Deactivate' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></section><?php require __DIR__.'/../includes/footer.php'; ?>
